		<field name="bolNum" type="String" def-value="" persistent="1" />
		<field name="locaTn" type="String" def-value="" persistent="1" />
		<field name="sumOfActQty" type="double" def-value="" persistent="1" />
		<field name="trlNum" type="String" def-value="" persistent="1" />
		<field name="rrNumb" type="String" def-value="" persistent="1" />
		<field name="itmCod" type="String" def-value="" persistent="1" />
		<field name="expQty" type="double" def-value="" persistent="1" />
		<field name="itmDsc" type="String" def-value="" persistent="1" />
	</object>

	<!--******** CLASSE RtcisStockView ******** -->
	<object name="RtcisStockView" class="procter.server.kanban.obj.RtcisStockView" table="param.RTCIS_STOCK_VIEW">
		<field name="ulid" type="String" def-value="" persistent="1" />
		<field name="locaTn" type="String" def-value="" persistent="1" />
		<field name="nbDays" type="double" def-value="" persistent="1" />
		<field name="itmCod" type="String" def-value="" persistent="1" />
		<field name="itmDsc" type="String" def-value="" persistent="1" />
		<field name="ctlGrp" type="String" def-value="" persistent="1" />
		<field name="qaStat" type="String" def-value="" persistent="1" />
		<field name="casQty" type="double" def-value="" persistent="1" />
		<field name="vendorLot" type="String" def-value="" persistent="1" />
		<field name="idLigneTremie" type="int" def-value="" persistent="1" read-only="1">
			<column name="RTCIS_RESERVATION_STOCK.idLigneTremie" />
		</field>
	</object>

	<!--******** CLASSE Seuil ******** -->
	<object name="Seuil" class="procter.server.kanban.obj.Seuil" table="param.SEUIL">
		<params>
			<param name="Log.HMIName" value="Seuil" />
		</params>
		<field name="id" type="int" def-value="" persistent="1" />
		<field name="idLigneTremie" type="int" def-value="" persistent="1" />
		<field name="idMaterialType" type="int" def-value="" persistent="1" />
		<field name="seuil" type="int" def-value="" persistent="1" />
		<field name="code" type="String" def-value="" persistent="1" read-only="1">
			<column name="MATERIAL_TYPE.code" />
		</field>
	</object>

	<!--******** CLASSE MailNotif ******** -->
	<object name="MailNotif" class="procter.server.kanban.obj.MailNotif" table="param.SYS_MAIL_NOTIF">
		<field name="id" type="int" def-value="" persistent="1" />
		<field name="categorie" type="String" def-value="" persistent="1" />
		<field name="value" type="String" def-value="" persistent="1" />
	</object>

	<!--******** CLASSE NavetteCalculHisto ******** -->
	<object name="NavetteCalculHisto" class="procter.server.kanban.obj.NavetteCalculHisto" table="param.NAVETTE_CALCUL_HISTO">
		<field name="id" type="int" def-value="" persistent="1" />
		<field name="idGcas" type="int" def-value="" persistent="1" />
		<field name="idNavette" type="int" def-value="" persistent="1" />
		<field name="horodate" type="Date" def-value="" persistent="1" />
		<field name="numero" type="int" def-value="" persistent="1" />
		<field name="resultat" type="String" def-value="" persistent="1" />
	</object>

	
	<object name="ParamCalculTubes" class="procter.server.kanban.tubescatroux.ParamCalculTubes" table="param.TUBES_CALCULS_PARAMS">
		<field name="id" type="int" def-value="" persistent="1" />
		<field name="dateButoir" type="Date" def-value="" persistent="1" />
		<field name="idLigne" type="int" def-value="" persistent="1" />		
	</object>
</object-mapping>